// Google Places (New) devuelve varias paginas, cada una con un array "places".
// Esto lo convierte en un item por negocio, con un placeId estable que sirve para deduplicar.
const cfg = $('Set niche, city and sheet name').first().json;
const out = [];

for (const item of $input.all()) {
  const places = item.json.places || [];
  for (const p of places) {
    const web = p.websiteUri || '';
    const addressParts = String(p.formattedAddress || '').split(',');
    // La direccion de Google termina en el pais: la localidad es la penultima parte
    // ("Av. Providencia 1234, Providencia, Santiago, Chile" -> Santiago).
    const locality = addressParts.length > 1
      ? addressParts[addressParts.length - 2].trim()
      : (cfg.ciudad || '');

    out.push({
      json: {
        placeId: p.id || '',
        nombre: (p.displayName && p.displayName.text) || '',
        categoria: (p.primaryTypeDisplayName && p.primaryTypeDisplayName.text) || p.primaryType || '',
        direccion: p.formattedAddress || '',
        localidad: locality,
        telefono: p.nationalPhoneNumber || p.internationalPhoneNumber || '',
        sitioWeb: web,
        tieneWeb: Boolean(web),
        rating: Number(p.rating || 0),
        resenas: Number(p.userRatingCount || 0),
        estadoNegocio: p.businessStatus || '',
        googleMaps: p.googleMapsUri || '',
        consulta: (cfg.nicho || '') + ' en ' + (cfg.ciudad || ''),
        capturadoEn: new Date().toISOString(),
      },
    });
  }
}

if (out.length === 0) {
  throw new Error('Google Places returned no results. Check the niche and the city in "Set niche, city and sheet name", and that Places API (New) is enabled for your key.');
}

return out;
